const wellnessJourneyJs = "/**\n * Mindful Paths — Signature Feature: \"Start Your Wellness Journey\"\n * Interactive Discovery Pathway Engine\n * Supports home-2.html and any legacy pages with robust null-guards\n */\n\n(function () {\n  'use strict';\n\n  const JOURNEY_DATA = {\n    anxiety: {\n      badge: 'Recommended Pathway: Anxiety & Nervous System Balance',\n      title: 'Cognitive Behavioral & Somatic Reset',\n      tagline: 'Grounded somatic pacing & evidence-based Cognitive Behavioral Therapy (CBT)',\n      service: 'Individual Therapy & CBT',\n      serviceUrl: 'service-individual-therapy.html',\n      frequency: '50-min weekly session',\n      format: 'In-Person or Telehealth',\n      opening: 'This Thursday 2:00 PM',\n      therapist: 'Dr. Sarah Jenkins, Psy.D.',\n      therapistRole: 'Lead Psychologist',\n      therapistUrl: 'therapist-details.html',\n      therapistImg: 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?auto=format&fit=crop&w=800&q=80',\n      quote: '“We don’t try to eliminate all anxiety—we help your nervous system realize it is safe right here.”',\n      description: 'Designed specifically for persistent tension, overthinking, and nervous system fatigue. We integrate cognitive restructuring with polyvagal somatic breathing to quiet mental noise and ground your body.'\n    },\n    relationships: {\n      badge: 'Recommended Pathway: Couples & Marriage Connection',\n      title: 'Gottman-Informed Relational Repair',\n      tagline: 'Gottman-informed communication, emotional safety, and conflict resolution',\n      service: 'Couples & Marriage Counseling',\n      serviceUrl: 'service-couples-therapy.html',\n      frequency: '60-min bi-weekly sessions',\n      format: 'Couples Suite or Dual Video',\n      opening: 'Friday at 3:30 PM',\n      therapist: 'Dr. Marcus Vance, LMFT',\n      therapistRole: 'Licensed Marriage & Family Therapist',\n      therapistUrl: 'therapist-details.html',\n      therapistImg: 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=800&q=80',\n      quote: '“Healthy relationships aren’t devoid of conflict; they possess the tools and safety to repair smoothly.”',\n      description: 'Move past defensive cycles into empathetic dialogue. Rebuild emotional safety, heal relational wounds, and rediscover shared intimacy in a supportive, judgment-free environment.'\n    },\n    trauma: {\n      badge: 'Recommended Pathway: Trauma Recovery & EMDR',\n      title: 'Bilateral Stimulation & Somatic Grounding',\n      tagline: 'Gentle desensitization, somatic stabilization, and nervous system safety',\n      service: 'Trauma Recovery & EMDR',\n      serviceUrl: 'service-trauma-emdr.html',\n      frequency: '60-min structured protocol',\n      format: 'In-Person Acoustic Suite',\n      opening: 'Next Monday 10:00 AM',\n      therapist: 'Elena Rostova, LCSW, CCTP',\n      therapistRole: 'Certified Trauma & EMDR Specialist',\n      therapistUrl: 'therapist-details.html',\n      therapistImg: 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=800&q=80',\n      quote: '“Trauma lives in the nervous system. We pace our work gently so your mind and body heal in harmony.”',\n      description: 'Gently process distressing memories and post-traumatic triggers without having to re-live every detail. Reprogram fight-or-flight somatic responses into embodied safety.'\n    },\n    growth: {\n      badge: 'Recommended Pathway: Mindfulness & Somatic Grounding',\n      title: 'Mindful Alignment & Deep Self-Inquiry',\n      tagline: 'Values alignment, overcoming imposter feelings, and mindful purpose',\n      service: 'Mindfulness & Somatic Grounding',\n      serviceUrl: 'service-mindfulness.html',\n      frequency: '50-min weekly or bi-weekly',\n      format: 'Garden Studio or Telehealth',\n      opening: 'Wednesday at 11:00 AM',\n      therapist: 'Dr. Maya Patel, Ph.D.',\n      therapistRole: 'Neuropsychologist & Mindfulness Lead',\n      therapistUrl: 'therapist-details.html',\n      therapistImg: 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80',\n      quote: '“When we cultivate stillness, we discover that clarity and wisdom were already waiting within us.”',\n      description: 'Connect with your inner values, dissolve persistent imposter syndrome, and cultivate unconditional self-compassion through somatic awareness and intentional life design.'\n    },\n    teen: {\n      badge: 'Recommended Pathway: Adolescent & Young Adult Mentorship',\n      title: 'Safe Harbor for Academic & Emotional Stress',\n      tagline: 'Relatable mentorship for academic burnout, social anxiety, and identity',\n      service: 'Teen & Adolescent Psychotherapy',\n      serviceUrl: 'service-teen-counseling.html',\n      frequency: '45-min weekly sessions',\n      format: 'Youth Loft or Secure App Video',\n      opening: 'Tomorrow at 4:30 PM',\n      therapist: 'James Thornton, LPC',\n      therapistRole: 'Adolescent & Family Specialist',\n      therapistUrl: 'therapist-details.html',\n      therapistImg: 'https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=800&q=80',\n      quote: '“Every young person deserves a space where their feelings are validated and their voice truly matters.”',\n      description: 'A genuine, non-clinical environment where teens feel respected and truly heard. Equipping young minds with emotional vocabulary, confidence, and stress resilience.'\n    },\n    burnout: {\n      badge: 'Recommended Pathway: Career Fatigue & High-Functioning Anxiety',\n      title: 'Executive Nervous System Reset & Boundaries',\n      tagline: 'Sustainable energy, boundary restoration, and holistic balance',\n      service: 'Telehealth Video Sessions',\n      serviceUrl: 'service-telehealth.html',\n      frequency: '50-min flexible scheduling',\n      format: 'Encrypted Telehealth (Global Access)',\n      opening: 'This Thursday 5:00 PM',\n      therapist: 'Dr. David Kim, M.D.',\n      therapistRole: 'Board-Certified Psychiatrist',\n      therapistUrl: 'therapist-details.html',\n      therapistImg: 'https://images.unsplash.com/photo-1537368910025-700350fe46c7?auto=format&fit=crop&w=800&q=80',\n      quote: '“Sustainable excellence requires honoring biological limits and creating authentic restorative margin.”',\n      description: 'Specialized protocol for entrepreneurs, executives, and clinicians facing chronic exhaustion. Establish healthy boundaries, recover physical vitality, and rebuild meaning.'\n    }\n  };\n\n  // Legacy aliases\n  JOURNEY_DATA.family = JOURNEY_DATA.relationships;\n  JOURNEY_DATA.transitions = JOURNEY_DATA.burnout;\n\n  function initWellnessJourney() {\n    const journeyBtns = document.querySelectorAll('.journey-btn, .journey-option-btn, [data-journey], [data-journey-key]');\n    const resultCard = document.getElementById('journey-result-card') || document.getElementById('journey-recommendation-card');\n\n    if (!journeyBtns.length) return;\n\n    function renderPathway(key) {\n      const data = JOURNEY_DATA[key] || JOURNEY_DATA.anxiety;\n\n      // Update button active styles\n      journeyBtns.forEach(btn => {\n        const btnKey = btn.getAttribute('data-journey') || btn.getAttribute('data-journey-key');\n        const isMatch = btnKey === key;\n\n        if (isMatch) {\n          btn.classList.add('active', 'border-[#D7B7A5]', 'bg-[#F8F6F1]', 'text-[#294657]', 'dark:bg-[#1e2d37]', 'dark:border-[#D7B7A5]', 'dark:text-[#F8F6F1]', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-[#17232b]', 'border-[#EBF1F4]', 'dark:border-white/10', 'text-[#27343B]', 'dark:text-[#EBF1F4]');\n        } else {\n          btn.classList.remove('active', 'border-[#D7B7A5]', 'bg-[#F8F6F1]', 'text-[#294657]', 'dark:bg-[#1e2d37]', 'dark:border-[#D7B7A5]', 'dark:text-[#F8F6F1]', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-[#17232b]', 'border-[#EBF1F4]', 'dark:border-white/10', 'text-[#27343B]', 'dark:text-[#EBF1F4]');\n        }\n      });\n\n      if (!resultCard) return;\n\n      // Smooth transition\n      resultCard.style.opacity = '0.35';\n      resultCard.style.transform = 'translateY(4px)';\n\n      setTimeout(() => {\n        // Direct home-2 targets\n        const badgeEl = document.getElementById('journey-badge');\n        const titleEl = document.getElementById('journey-title');\n        const descEl = document.getElementById('journey-description');\n        const freqEl = document.getElementById('journey-frequency');\n        const formatEl = document.getElementById('journey-format');\n        const openEl = document.getElementById('journey-opening');\n        const imgEl = document.getElementById('journey-therapist-img');\n        const specEl = document.getElementById('journey-therapist-spec');\n        const nameEl = document.getElementById('journey-therapist-name');\n        const quoteEl = document.getElementById('journey-therapist-quote');\n\n        if (badgeEl) badgeEl.textContent = data.badge;\n        if (titleEl) titleEl.textContent = data.title;\n        if (descEl) descEl.textContent = data.description;\n        if (freqEl) freqEl.textContent = data.frequency;\n        if (formatEl) formatEl.textContent = data.format;\n        if (openEl) openEl.textContent = data.opening;\n        if (imgEl) {\n          imgEl.src = data.therapistImg;\n          imgEl.alt = data.therapist;\n        }\n        if (specEl) specEl.textContent = data.therapistRole;\n        if (nameEl) nameEl.textContent = data.therapist;\n        if (quoteEl) quoteEl.innerHTML = `&ldquo;${data.quote.replace(/[“”\"]/g, '')}&rdquo;`;\n\n        // Update appointment booking button data attributes\n        const bookBtn = resultCard.querySelector('.open-appointment-btn, .open-appointment-modal');\n        if (bookBtn) {\n          bookBtn.setAttribute('data-service', data.service);\n          bookBtn.setAttribute('data-therapist', data.therapist);\n        }\n\n        // Legacy container support\n        const legacyContainer = document.getElementById('journey-recommendation-card');\n        if (legacyContainer && !badgeEl) {\n          legacyContainer.innerHTML = `\n            <div class=\"p-8 sm:p-10 rounded-3xl bg-white dark:bg-[#17232b] border border-[#8FAFC0]/30 shadow-xl space-y-6\">\n              <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-6 border-b border-stone-200 dark:border-white/10\">\n                <div>\n                  <span class=\"inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#8FAFC0]/15 text-[#294657] dark:text-[#8FAFC0] text-xs font-bold uppercase tracking-wider\">\n                    <i class=\"fas fa-sparkles\"></i> Recommended Pathway\n                  </span>\n                  <h3 class=\"font-heading text-2xl sm:text-3xl font-bold text-[#294657] dark:text-white mt-2\">${data.title}</h3>\n                  <p class=\"text-xs text-stone-500 dark:text-stone-400 mt-1\">${data.tagline}</p>\n                </div>\n                <div class=\"text-right rtl:text-left shrink-0\">\n                  <span class=\"text-xs text-stone-400\">Next Available Intake</span>\n                  <p class=\"text-xs font-bold text-[#D7B7A5] flex items-center sm:justify-end gap-1\"><i class=\"far fa-clock\"></i> ${data.opening}</p>\n                </div>\n              </div>\n\n              <p class=\"text-sm text-stone-600 dark:text-stone-300 leading-relaxed font-normal\">${data.description}</p>\n\n              <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6 pt-2\">\n                <a href=\"${data.therapistUrl}\" class=\"flex items-center gap-4 p-4 rounded-2xl bg-[#F8F6F1]/70 dark:bg-[#11191f]/70 border border-stone-200/60 dark:border-white/5 hover:border-[#D7B7A5]/50 hover:shadow-md transition-all group\" title=\"View ${data.therapist} Profile\">\n                  <img src=\"${data.therapistImg}\" alt=\"${data.therapist}\" class=\"w-14 h-14 rounded-2xl object-cover border-2 border-[#8FAFC0]/60 shadow-sm group-hover:scale-105 transition-transform\">\n                  <div>\n                    <span class=\"text-[10px] font-bold text-[#D7B7A5] uppercase tracking-wider\">Matched Clinician</span>\n                    <h4 class=\"font-heading text-base font-bold text-[#294657] dark:text-white group-hover:text-[#D7B7A5] transition-colors flex items-center gap-1.5\">\n                      ${data.therapist} <i class=\"fas fa-arrow-right text-[10px] opacity-0 group-hover:opacity-100 transition-opacity\"></i>\n                    </h4>\n                    <p class=\"text-xs text-stone-500 dark:text-stone-400\">${data.therapistRole}</p>\n                  </div>\n                </a>\n\n                <a href=\"${data.serviceUrl}\" class=\"flex flex-col justify-center p-4 rounded-2xl bg-[#F8F6F1]/70 dark:bg-[#11191f]/70 border border-stone-200/60 dark:border-white/5 hover:border-[#D7B7A5]/50 hover:shadow-md transition-all group\" title=\"Explore ${data.service} Details\">\n                  <div class=\"flex items-center justify-between\">\n                    <span class=\"text-[10px] font-bold text-[#294657] dark:text-[#8FAFC0] uppercase tracking-wider\">Service &amp; Modality</span>\n                    <span class=\"text-[10px] font-bold text-[#D7B7A5] group-hover:underline flex items-center gap-1\">Details <i class=\"fas fa-arrow-right text-[9px]\"></i></span>\n                  </div>\n                  <h4 class=\"text-xs font-bold text-stone-800 dark:text-white mt-0.5 group-hover:text-[#D7B7A5] transition-colors\">${data.service}</h4>\n                  <p class=\"text-xs text-stone-500 dark:text-stone-400 mt-0.5\"><i class=\"fas fa-shield-alt text-[#8FAFC0] mr-1\"></i> ${data.format}</p>\n                </a>\n              </div>\n\n              <div class=\"pt-4 flex flex-col sm:flex-row items-center justify-between gap-4\">\n                <div class=\"flex items-center gap-2 text-xs text-stone-500 dark:text-stone-400\">\n                  <i class=\"fas fa-check-circle text-[#8FAFC0]\"></i> No referral needed &bull; 100% HIPAA protected\n                </div>\n                <button type=\"button\" class=\"open-appointment-modal w-full sm:w-auto px-8 h-12 rounded-full bg-[#D7B7A5] hover:bg-[#b8937f] text-white font-bold text-xs shadow-lg shadow-[#D7B7A5]/30 transition-all hover:scale-105 active:scale-95 flex items-center justify-center gap-2\" data-service=\"${data.service}\" data-therapist=\"${data.therapist}\">\n                  <span>Book This Pathway</span>\n                  <i class=\"fas fa-arrow-right text-xs\"></i>\n                </button>\n              </div>\n            </div>\n          `;\n        }\n\n        resultCard.style.opacity = '1';\n        resultCard.style.transform = 'translateY(0)';\n      }, 150);\n    }\n\n    journeyBtns.forEach(btn => {\n      btn.addEventListener('click', (e) => {\n        e.preventDefault();\n        const key = btn.getAttribute('data-journey') || btn.getAttribute('data-journey-key');\n        if (key) {\n          renderPathway(key);\n        }\n      });\n    });\n\n    // Default selection\n    renderPathway('anxiety');\n  }\n\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', initWellnessJourney);\n  } else {\n    initWellnessJourney();\n  }\n})();\n";
const breathingJs = "/**\n * Mindful Paths — Interactive \"Take a Breath\" Tool\n * 4-4-4-4 Clinical Box Breathing Engine\n * Works across home-2.html, resources.html, and all demo widgets\n */\n\n(function () {\n  'use strict';\n\n  let breathingActive = false;\n  let timerInterval = null;\n  let currentSeconds = 4;\n  let currentPhaseIndex = 0;\n  let cycleCount = 0;\n\n  const PHASES = [\n    { name: 'Inhale Slowly', prompt: 'Fill your lungs with cool, calming air', scaleClass: 'scale-115', auraClass: 'scale-125 bg-[#8FAFC0]/35' },\n    { name: 'Hold Breath', prompt: 'Remain centered and peaceful in stillness', scaleClass: 'scale-115', auraClass: 'scale-120 bg-[#8FAFC0]/30' },\n    { name: 'Exhale Gently', prompt: 'Release all tension, hurry, and stress', scaleClass: 'scale-90', auraClass: 'scale-90 bg-[#294657]/20' },\n    { name: 'Hold Empty', prompt: 'Rest calmly before the next gentle breath', scaleClass: 'scale-90', auraClass: 'scale-85 bg-[#294657]/15' }\n  ];\n\n  function initBreathingTool() {\n    const circle = document.getElementById('breathing-circle');\n    const aura = document.getElementById('breathing-aura');\n    const stageEl = document.getElementById('breathing-stage') || document.getElementById('breathing-phase-text');\n    const timerEl = document.getElementById('breathing-timer') || document.getElementById('breathing-timer-text');\n    const cyclesEl = document.getElementById('breathing-cycles') || document.getElementById('breathing-cycles-completed');\n    const startBtn = document.getElementById('breathing-start-btn') || document.getElementById('breathing-toggle-btn');\n    const resetBtn = document.getElementById('breathing-reset-btn');\n\n    if (!circle || !startBtn) return;\n\n    function updateVisuals() {\n      const p = PHASES[currentPhaseIndex];\n      if (stageEl) stageEl.textContent = p.name;\n      if (timerEl) timerEl.textContent = `${currentSeconds}s`;\n      if (cyclesEl) {\n        if (cyclesEl.id === 'breathing-cycles') {\n          cyclesEl.textContent = `Cycle ${cycleCount}/4`;\n        } else {\n          cyclesEl.textContent = cycleCount;\n        }\n      }\n\n      if (circle) {\n        circle.classList.remove('scale-115', 'scale-90', 'scale-125');\n        circle.classList.add(p.scaleClass);\n      }\n\n      if (aura) {\n        aura.className = `absolute inset-0 rounded-full blur-xl transition-all duration-1000 transform ${p.auraClass}`;\n      }\n    }\n\n    function tick() {\n      if (currentSeconds > 1) {\n        currentSeconds--;\n        if (timerEl) timerEl.textContent = `${currentSeconds}s`;\n      } else {\n        currentSeconds = 4;\n        currentPhaseIndex = (currentPhaseIndex + 1) % PHASES.length;\n\n        if (currentPhaseIndex === 0) {\n          cycleCount++;\n          if (cycleCount === 4 && window.showToast) {\n            window.showToast('Wonderful work! You have completed 4 full mindful cycles of box breathing.', 'success', 5000);\n          }\n        }\n\n        updateVisuals();\n      }\n    }\n\n    function start() {\n      breathingActive = true;\n      startBtn.innerHTML = '<i class=\"fas fa-pause mr-1.5\"></i> Pause Breathing';\n      startBtn.classList.remove('bg-[#D7B7A5]');\n      startBtn.classList.add('bg-[#294657]');\n      updateVisuals();\n      timerInterval = setInterval(tick, 1000);\n    }\n\n    function pause() {\n      breathingActive = false;\n      clearInterval(timerInterval);\n      startBtn.innerHTML = '<i class=\"fas fa-play mr-1.5\"></i> Resume Breathing';\n      startBtn.classList.remove('bg-[#294657]');\n      startBtn.classList.add('bg-[#D7B7A5]');\n    }\n\n    function reset() {\n      breathingActive = false;\n      clearInterval(timerInterval);\n      currentSeconds = 4;\n      currentPhaseIndex = 0;\n      cycleCount = 0;\n\n      startBtn.innerHTML = '<i class=\"fas fa-play mr-1.5\"></i> Begin 4-4-4 Breathing';\n      startBtn.classList.remove('bg-[#294657]');\n      startBtn.classList.add('bg-[#D7B7A5]');\n\n      if (stageEl) stageEl.textContent = 'Ready';\n      if (timerEl) timerEl.textContent = 'Press Start Below';\n      if (cyclesEl) {\n        if (cyclesEl.id === 'breathing-cycles') {\n          cyclesEl.textContent = 'Cycle 0/4';\n        } else {\n          cyclesEl.textContent = '0';\n        }\n      }\n\n      if (circle) {\n        circle.classList.remove('scale-115', 'scale-125');\n        circle.classList.add('scale-90');\n      }\n\n      if (aura) {\n        aura.className = 'absolute inset-0 rounded-full bg-[#8FAFC0]/20 blur-xl transition-transform duration-1000 transform scale-90';\n      }\n    }\n\n    startBtn.addEventListener('click', () => {\n      if (breathingActive) pause();\n      else start();\n    });\n\n    if (resetBtn) {\n      resetBtn.addEventListener('click', reset);\n    }\n  }\n\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', initBreathingTool);\n  } else {\n    initBreathingTool();\n  }\n})();\n";
const moodJournalJs = "/**\n * Mindful Paths — Client Mood Journal Engine\n * Connects mood-journal.html, dashboard.html, and home-2.html preview\n */\n\n(function () {\n  'use strict';\n\n  const STORAGE_KEY = 'mindfulpaths_mood_logs';\n\n  const MOOD_DATA = {\n    great: { label: 'Great', emoji: '😊', score: 5, color: '#8FAFC0' },\n    good: { label: 'Good', emoji: '🙂', score: 4, color: '#7BAE7F' },\n    okay: { label: 'Okay', emoji: '😐', score: 3, color: '#D4A373' },\n    low: { label: 'Low', emoji: '😔', score: 2, color: '#D7B7A5' },\n    difficult: { label: 'Difficult', emoji: '😣', score: 1, color: '#9E2A2B' }\n  };\n\n  function getLogs() {\n    try {\n      const data = localStorage.getItem(STORAGE_KEY);\n      return data ? JSON.parse(data) : [];\n    } catch (e) {\n      return [];\n    }\n  }\n\n  function saveLog(moodKey, reflection = '') {\n    const logs = getLogs();\n    const entry = {\n      id: Date.now(),\n      mood: moodKey,\n      moodInfo: MOOD_DATA[moodKey] || MOOD_DATA.good,\n      reflection: reflection.trim(),\n      date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),\n      time: new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })\n    };\n    logs.unshift(entry);\n    localStorage.setItem(STORAGE_KEY, JSON.stringify(logs.slice(0, 40)));\n    return entry;\n  }\n\n  function initMoodJournal() {\n    let selectedMood = 'good';\n\n    // 1. Selector buttons on mood-journal.html & dashboard.html\n    const selectorContainer = document.getElementById('mood-journal-selector');\n    const moodBtns = selectorContainer \n      ? selectorContainer.querySelectorAll('button') \n      : document.querySelectorAll('.mood-selector-btn, [data-mood]');\n\n    moodBtns.forEach(btn => {\n      btn.addEventListener('click', (e) => {\n        e.preventDefault();\n        moodBtns.forEach(b => {\n          b.classList.remove('border-[#D7B7A5]', 'bg-[#D7B7A5]/10', 'scale-105', 'active');\n          b.classList.add('border-transparent');\n        });\n        btn.classList.add('border-[#D7B7A5]', 'bg-[#D7B7A5]/10', 'scale-105', 'active');\n        btn.classList.remove('border-transparent');\n\n        const mood = btn.getAttribute('data-mood');\n        if (mood) selectedMood = mood;\n      });\n    });\n\n    // 2. Note input & Submit button on mood-journal.html\n    const noteInput = document.getElementById('journal-notes-input') || document.getElementById('mood-reflection-input');\n    const submitBtn = document.getElementById('journal-submit-btn') || document.getElementById('save-mood-entry-btn');\n    const historyList = document.getElementById('journal-history-list') || document.getElementById('mood-history-list');\n\n    function renderHistory() {\n      if (!historyList) return;\n      const logs = getLogs();\n      if (!logs.length) {\n        historyList.innerHTML = '<div class=\"p-6 text-center text-xs text-[#27343B]/70 dark:text-white/40\">No journal reflections recorded yet. Your reflections remain 100% private to your encrypted device.</div>';\n        return;\n      }\n\n      historyList.innerHTML = logs.slice(0, 10).map(log => `\n        <div class=\"p-4 rounded-2xl bg-[#F8F6F1] dark:bg-[#1e2d37] border border-[#EBF1F4] dark:border-white/10 space-y-2\">\n          <div class=\"flex items-center justify-between\">\n            <div class=\"flex items-center gap-2\">\n              <span class=\"text-xl\">${log.moodInfo.emoji}</span>\n              <span class=\"text-xs font-bold text-[#294657] dark:text-white\">${log.moodInfo.label}</span>\n            </div>\n            <span class=\"text-[10px] text-[#27343B]/70 dark:text-white/40\">${log.date} &bull; ${log.time}</span>\n          </div>\n          ${log.reflection ? `<p class=\"text-xs text-[#27343B] dark:text-[#EBF1F4] leading-relaxed bg-white/70 dark:bg-[#17232b]/70 p-3 rounded-xl border border-[#EBF1F4]/60 dark:border-white/5\">${log.reflection}</p>` : ''}\n        </div>\n      `).join('');\n    }\n\n    if (submitBtn) {\n      submitBtn.addEventListener('click', (e) => {\n        e.preventDefault();\n        const text = noteInput ? noteInput.value : '';\n        saveLog(selectedMood, text);\n        if (noteInput) noteInput.value = '';\n        renderHistory();\n        if (window.showToast) {\n          window.showToast('Mood check-in saved safely to your private sanctuary.', 'success');\n        }\n      });\n    }\n\n    // 3. Dashboard quick mood logger\n    const dashMoodSave = document.getElementById('dashboard-mood-save');\n    const dashMoodNote = document.getElementById('dashboard-mood-note');\n    if (dashMoodSave) {\n      dashMoodSave.addEventListener('click', (e) => {\n        e.preventDefault();\n        const text = dashMoodNote ? dashMoodNote.value : '';\n        saveLog('good', text);\n        if (dashMoodNote) dashMoodNote.value = '';\n        if (window.showToast) {\n          window.showToast('Daily reflection saved to your Sanctuary timeline.', 'success');\n        }\n      });\n    }\n\n    // 4. Home-2 preview mood emojis\n    document.querySelectorAll('.mock-mood-emoji, [data-home-mood]').forEach(emojiEl => {\n      emojiEl.addEventListener('click', () => {\n        const mood = emojiEl.getAttribute('data-home-mood') || 'good';\n        saveLog(mood, 'Quick check-in from The Wellness Journey');\n        if (window.showToast) {\n          window.showToast('Mood logged! You can review past trends in your Client Sanctuary.', 'info');\n        }\n      });\n    });\n\n    renderHistory();\n  }\n\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', initMoodJournal);\n  } else {\n    initMoodJournal();\n  }\n})();\n";
const messagingJs = "/**\n * Mindful Paths — Counselor Messaging Interface\n * Asynchronous encrypted check-ins with realistic clinician simulated responses\n */\n\n(function () {\n  'use strict';\n\n  function initMessaging() {\n    const threadContainer = document.getElementById('chat-messages-stream') || document.getElementById('chat-thread');\n    const composerForm = document.getElementById('chat-composer-form');\n    const composerInput = document.getElementById('chat-input-text');\n    const sendBtn = document.getElementById('chat-send-btn');\n    const quickReplies = document.querySelectorAll('.quick-reply-pill');\n\n    if (!threadContainer || !composerInput) return;\n\n    function sendMessage(text) {\n      if (!text || !text.trim()) return;\n\n      const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });\n\n      // Append Client Message\n      const clientMsg = document.createElement('div');\n      clientMsg.className = 'flex justify-end gap-3 items-end animate-fade-in';\n      clientMsg.innerHTML = `\n        <div class=\"space-y-1 max-w-md\">\n          <div class=\"p-3.5 rounded-2xl rounded-br-sm bg-[#294657] text-white text-xs leading-relaxed shadow-sm font-normal\">\n            ${text}\n          </div>\n          <div class=\"flex justify-end items-center gap-1 text-[10px] text-stone-400\">\n            <span>${timeStr}</span>\n            <i class=\"fas fa-check-double text-[#8FAFC0]\"></i>\n          </div>\n        </div>\n      `;\n      threadContainer.appendChild(clientMsg);\n      threadContainer.scrollTop = threadContainer.scrollHeight;\n\n      composerInput.value = '';\n\n      // Simulated Clinician Reply after 1.2s\n      setTimeout(() => {\n        const counselorMsg = document.createElement('div');\n        counselorMsg.className = 'flex items-end gap-3 animate-fade-in';\n        counselorMsg.innerHTML = `\n          <img src=\"https://images.unsplash.com/photo-1559839734-2b71ea197ec2?auto=format&fit=crop&w=120&q=80\" alt=\"Dr. Sarah Jenkins\" class=\"w-8 h-8 rounded-full object-cover border-2 border-[#8FAFC0]/40 shadow-sm shrink-0\">\n          <div class=\"space-y-1 max-w-md\">\n            <div class=\"p-3.5 rounded-2xl rounded-bl-sm bg-white dark:bg-[#17232b] text-[#294657] dark:text-[#F8F6F1] border border-[#EBF1F4] dark:border-white/10 text-xs leading-relaxed shadow-sm font-normal\">\n              Thank you for sharing this with me, Alex. I hear how much you've been carrying this week. We will gently explore practical grounding anchors for this during our upcoming session tomorrow. Remember to take a mindful breath when you feel the surge.\n            </div>\n            <span class=\"text-[10px] text-stone-400 pl-1\">${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} &bull; Encrypted Portal</span>\n          </div>\n        `;\n        threadContainer.appendChild(counselorMsg);\n        threadContainer.scrollTop = threadContainer.scrollHeight;\n\n        if (window.showToast) {\n          window.showToast('Dr. Sarah Jenkins replied to your message in the sanctuary.', 'info');\n        }\n      }, 1200);\n    }\n\n    if (composerForm) {\n      composerForm.addEventListener('submit', (e) => {\n        e.preventDefault();\n        sendMessage(composerInput.value);\n      });\n    }\n\n    if (sendBtn) {\n      sendBtn.addEventListener('click', (e) => {\n        e.preventDefault();\n        sendMessage(composerInput.value);\n      });\n    }\n\n    composerInput.addEventListener('keydown', (e) => {\n      if (e.key === 'Enter' && !e.shiftKey) {\n        e.preventDefault();\n        sendMessage(composerInput.value);\n      }\n    });\n\n    quickReplies.forEach(pill => {\n      pill.addEventListener('click', () => {\n        sendMessage(pill.textContent.trim());\n      });\n    });\n  }\n\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', initMessaging);\n  } else {\n    initMessaging();\n  }\n})();\n";
const mainJs = "/**\n * Mindful Paths — Core JavaScript Engine\n * Author: Mindful Paths Psychological Sanctuary\n * Version: 5.0.0 (Unified Universal System)\n * Pure Vanilla JS: Theme, RTL, Booking Modal, Contact Inquiry, Pricing Toggle, Search/Filter, Toasts\n */\n\n(function () {\n  'use strict';\n\n  // ==========================================\n  // 1. Theme Manager (Dark / Light Mode)\n  // ==========================================\n  function initTheme() {\n    const savedTheme = localStorage.getItem('mindfulpaths_theme') || localStorage.getItem('calmind_theme') || localStorage.getItem('serenemind_theme');\n    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;\n\n    if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {\n      document.documentElement.classList.add('dark');\n      updateThemeIcons(true);\n    } else {\n      document.documentElement.classList.remove('dark');\n      updateThemeIcons(false);\n    }\n  }\n\n  function toggleTheme() {\n    const isDark = document.documentElement.classList.toggle('dark');\n    localStorage.setItem('mindfulpaths_theme', isDark ? 'dark' : 'light');\n    localStorage.setItem('calmind_theme', isDark ? 'dark' : 'light');\n    localStorage.setItem('serenemind_theme', isDark ? 'dark' : 'light');\n    updateThemeIcons(isDark);\n    if (window.showToast) {\n      window.showToast(`Switched to ${isDark ? 'Dark' : 'Light'} Mode`, 'info', 2500);\n    }\n  }\n\n  function updateThemeIcons(isDark) {\n    document.querySelectorAll('.theme-toggle-btn').forEach(btn => {\n      const sunIcon = btn.querySelector('.sun-icon, .fa-sun');\n      const moonIcon = btn.querySelector('.moon-icon, .fa-moon');\n      const label = btn.querySelector('.theme-label');\n      if (sunIcon && moonIcon) {\n        if (isDark) {\n          sunIcon.classList.remove('hidden');\n          moonIcon.classList.add('hidden');\n          if (label) label.textContent = 'Light';\n        } else {\n          sunIcon.classList.add('hidden');\n          moonIcon.classList.remove('hidden');\n          if (label) label.textContent = 'Dark';\n        }\n      }\n    });\n  }\n\n  document.addEventListener('click', (e) => {\n    const themeBtn = e.target.closest('.theme-toggle-btn');\n    if (themeBtn) {\n      e.preventDefault();\n      toggleTheme();\n    }\n  });\n\n  // ==========================================\n  // 2. RTL Engine (Right-To-Left)\n  // ==========================================\n  function initRTL() {\n    const savedRTL = localStorage.getItem('mindfulpaths_direction') || localStorage.getItem('calmind_direction') || localStorage.getItem('serenemind_direction');\n    if (savedRTL === 'rtl') {\n      document.documentElement.setAttribute('dir', 'rtl');\n      updateRTLBtns(true);\n    } else {\n      document.documentElement.setAttribute('dir', 'ltr');\n      updateRTLBtns(false);\n    }\n  }\n\n  function toggleRTL() {\n    const currentDir = document.documentElement.getAttribute('dir') || 'ltr';\n    const newDir = currentDir === 'ltr' ? 'rtl' : 'ltr';\n    document.documentElement.setAttribute('dir', newDir);\n    localStorage.setItem('mindfulpaths_direction', newDir);\n    localStorage.setItem('calmind_direction', newDir);\n    localStorage.setItem('serenemind_direction', newDir);\n    updateRTLBtns(newDir === 'rtl');\n    if (window.showToast) {\n      window.showToast(`Layout switched to ${newDir.toUpperCase()}`, 'info', 2500);\n    }\n  }\n\n  function updateRTLBtns(isRTL) {\n    document.querySelectorAll('.rtl-toggle-btn').forEach(btn => {\n      const textSpan = btn.querySelector('.rtl-text');\n      if (textSpan) textSpan.textContent = isRTL ? 'LTR' : 'RTL';\n    });\n  }\n\n  document.addEventListener('click', (e) => {\n    const rtlBtn = e.target.closest('.rtl-toggle-btn');\n    if (rtlBtn) {\n      e.preventDefault();\n      toggleRTL();\n    }\n  });\n\n  // Run Theme and RTL immediately\n  initTheme();\n  initRTL();\n\n  // ==========================================\n  // 3. Mobile Navigation Drawer\n  // ==========================================\n  const mobileMenuToggle = document.getElementById('mobile-menu-toggle');\n  const mobileMenuDrawer = document.getElementById('mobile-menu-drawer');\n  const mobileMenuBackdrop = document.getElementById('mobile-menu-backdrop');\n  const mobileMenuClose = document.getElementById('mobile-menu-close');\n\n  function openMobileMenu() {\n    if (mobileMenuDrawer && mobileMenuBackdrop) {\n      mobileMenuDrawer.classList.remove('translate-x-full', '-translate-x-full');\n      mobileMenuDrawer.classList.add('translate-x-0');\n      mobileMenuBackdrop.classList.remove('opacity-0', 'pointer-events-none');\n      mobileMenuBackdrop.classList.add('opacity-100', 'pointer-events-auto');\n      document.body.style.overflow = 'hidden';\n    }\n  }\n\n  function closeMobileMenu() {\n    if (mobileMenuDrawer && mobileMenuBackdrop) {\n      const isRTL = document.documentElement.getAttribute('dir') === 'rtl';\n      if (isRTL) {\n        mobileMenuDrawer.classList.add('-translate-x-full');\n      } else {\n        mobileMenuDrawer.classList.add('translate-x-full');\n      }\n      mobileMenuDrawer.classList.remove('translate-x-0');\n      mobileMenuBackdrop.classList.add('opacity-0', 'pointer-events-none');\n      mobileMenuBackdrop.classList.remove('opacity-100', 'pointer-events-auto');\n      document.body.style.overflow = '';\n    }\n  }\n\n  if (mobileMenuToggle) mobileMenuToggle.addEventListener('click', openMobileMenu);\n  if (mobileMenuClose) mobileMenuClose.addEventListener('click', closeMobileMenu);\n  if (mobileMenuBackdrop) mobileMenuBackdrop.addEventListener('click', closeMobileMenu);\n\n  if (mobileMenuDrawer) {\n    mobileMenuDrawer.querySelectorAll('a').forEach(link => {\n      link.addEventListener('click', closeMobileMenu);\n    });\n  }\n\n  // ==========================================\n  // 4. Universal Appointment Booking Modal\n  // ==========================================\n  const appointmentModal = document.getElementById('appointment-modal');\n  const appointmentForm = document.getElementById('appointment-booking-form');\n\n  function openAppointmentModal(service = '', therapist = '') {\n    if (!appointmentModal) return;\n    appointmentModal.classList.remove('hidden');\n    appointmentModal.classList.add('flex');\n    document.body.style.overflow = 'hidden';\n\n    // Auto-prefill service/therapist if fields exist\n    if (service && appointmentForm) {\n      const serviceSelect = appointmentForm.querySelector('select[name=\"service\"]');\n      if (serviceSelect) {\n        for (let i = 0; i < serviceSelect.options.length; i++) {\n          if (serviceSelect.options[i].text.toLowerCase().includes(service.toLowerCase()) || serviceSelect.options[i].value.toLowerCase().includes(service.toLowerCase())) {\n            serviceSelect.selectedIndex = i;\n            break;\n          }\n        }\n      }\n    }\n    if (therapist && appointmentForm) {\n      const therapistSelect = appointmentForm.querySelector('select[name=\"therapist\"]');\n      if (therapistSelect) {\n        for (let i = 0; i < therapistSelect.options.length; i++) {\n          if (therapistSelect.options[i].text.toLowerCase().includes(therapist.toLowerCase()) || therapistSelect.options[i].value.toLowerCase().includes(therapist.toLowerCase())) {\n            therapistSelect.selectedIndex = i;\n            break;\n          }\n        }\n      }\n    }\n  }\n\n  function closeAppointmentModal() {\n    if (!appointmentModal) return;\n    appointmentModal.classList.add('hidden');\n    appointmentModal.classList.remove('flex');\n    document.body.style.overflow = '';\n  }\n\n  document.addEventListener('click', (e) => {\n    const bookTrigger = e.target.closest('.open-appointment-modal, .open-appointment-btn, [data-book-session]');\n    if (bookTrigger) {\n      e.preventDefault();\n      const service = bookTrigger.getAttribute('data-service') || '';\n      const therapist = bookTrigger.getAttribute('data-therapist') || '';\n      openAppointmentModal(service, therapist);\n    }\n\n    const closeBtn = e.target.closest('#appointment-modal-close, .close-appointment-modal');\n    if (closeBtn) {\n      e.preventDefault();\n      closeAppointmentModal();\n    }\n\n    if (e.target === appointmentModal) {\n      closeAppointmentModal();\n    }\n  });\n\n  document.addEventListener('keydown', (e) => {\n    if (e.key === 'Escape') {\n      closeAppointmentModal();\n      closeMobileMenu();\n    }\n  });\n\n  if (appointmentForm) {\n    appointmentForm.addEventListener('submit', (e) => {\n      e.preventDefault();\n      const submitBtn = appointmentForm.querySelector('button[type=\"submit\"]');\n      if (submitBtn) {\n        submitBtn.disabled = true;\n        submitBtn.innerHTML = '<i class=\"fas fa-circle-notch fa-spin mr-2\"></i> Confirming with Care Coordinator...';\n      }\n\n      setTimeout(() => {\n        if (submitBtn) {\n          submitBtn.disabled = false;\n          submitBtn.innerHTML = '<i class=\"fas fa-check mr-2\"></i> Request Received';\n        }\n        closeAppointmentModal();\n        appointmentForm.reset();\n        window.showToast('Appointment request sent! Our clinical intake coordinator will call you within 2 business hours.', 'success', 6000);\n      }, 1000);\n    });\n  }\n\n  // ==========================================\n  // 5. Contact & General Inquiry Form Handler\n  // ==========================================\n  const contactForm = document.getElementById('contact-inquiry-form') || document.querySelector('section form');\n  if (contactForm && !contactForm.id.includes('appointment')) {\n    contactForm.addEventListener('submit', (e) => {\n      e.preventDefault();\n      const submitBtn = contactForm.querySelector('button[type=\"submit\"]');\n      if (submitBtn) {\n        submitBtn.disabled = true;\n        submitBtn.innerHTML = '<i class=\"fas fa-circle-notch fa-spin mr-2\"></i> Sending Confidential Inquiry...';\n      }\n\n      setTimeout(() => {\n        if (submitBtn) {\n          submitBtn.disabled = false;\n          submitBtn.innerHTML = 'Send Inquiry';\n        }\n        contactForm.reset();\n        window.showToast('Thank you for reaching out. A client intake specialist will respond to your confidential inquiry shortly.', 'success', 6000);\n      }, 900);\n    });\n  }\n\n  // ==========================================\n  // 6. Interactive Mental Wellness Screener (PHQ-9 / GAD-7)\n  // ==========================================\n  const screenerForm = document.getElementById('wellness-screener-form');\n  const screenerResult = document.getElementById('screener-result');\n\n  if (screenerForm) {\n    screenerForm.addEventListener('submit', (e) => {\n      e.preventDefault();\n      const radios = screenerForm.querySelectorAll('input[type=\"radio\"]:checked');\n      if (radios.length < 3) {\n        window.showToast('Please answer all questions to generate your clinical insight.', 'error');\n        return;\n      }\n\n      let score = 0;\n      radios.forEach(r => { score += parseInt(r.value, 10); });\n\n      let title = '';\n      let text = '';\n      let badgeColor = '';\n\n      if (score <= 2) {\n        title = 'Minimal Emotional Distress (Score: ' + score + '/9)';\n        text = 'Your responses indicate mild everyday stressors. Mindful breathing, proper sleep hygiene, and preventive self-help routines can help you maintain this healthy baseline.';\n        badgeColor = 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950/70 dark:text-emerald-300';\n      } else if (score <= 5) {\n        title = 'Mild to Moderate Stress Burden (Score: ' + score + '/9)';\n        text = 'You are experiencing notable stress or situational anxiety. A few targeted counseling sessions focusing on Cognitive Restructuring or EMDR grounding could provide immediate relief.';\n        badgeColor = 'bg-amber-100 text-amber-800 dark:bg-amber-950/70 dark:text-amber-300';\n      } else {\n        title = 'Elevated Anxiety or Depressive Fatigue (Score: ' + score + '/9)';\n        text = 'Your stress level is significantly impacting your daily wellbeing. We strongly recommend speaking with one of our licensed clinical psychologists for a personalized, judgment-free intake session.';\n        badgeColor = 'bg-rose-100 text-rose-800 dark:bg-rose-950/70 dark:text-rose-300';\n      }\n\n      if (screenerResult) {\n        screenerResult.innerHTML = `\n          <div class=\"p-6 rounded-2xl border border-[#EBF1F4] dark:border-white/10 bg-white dark:bg-[#17232b] shadow-xl space-y-4 animate-fade-in\">\n            <div class=\"flex items-center justify-between\">\n              <span class=\"px-3 py-1 rounded-full text-xs font-bold ${badgeColor}\">\n                <i class=\"fas fa-shield-heart mr-1.5\"></i> Screener Result\n              </span>\n              <button type=\"button\" class=\"text-xs text-stone-400 hover:text-stone-600 dark:hover:text-stone-200\" onclick=\"document.getElementById('screener-result').innerHTML = '';\">\n                <i class=\"fas fa-redo mr-1\"></i> Retake\n              </button>\n            </div>\n            <h4 class=\"text-lg font-heading font-bold text-[#294657] dark:text-white\">${title}</h4>\n            <p class=\"text-sm text-[#27343B] dark:text-[#EBF1F4] leading-relaxed\">${text}</p>\n            <div class=\"pt-2 flex flex-col sm:flex-row gap-3\">\n              <button type=\"button\" class=\"open-appointment-modal px-5 py-2.5 rounded-full bg-[#D7B7A5] hover:bg-[#c5a390] text-white font-bold text-xs shadow-md\">\n                <i class=\"fas fa-calendar-check mr-2\"></i> Book Free 15-Min Consultation\n              </button>\n              <a href=\"resources.html\" class=\"px-5 py-2.5 rounded-full bg-[#F8F6F1] dark:bg-[#1e2d37] text-[#294657] dark:text-[#F8F6F1] font-bold text-xs text-center border border-[#EBF1F4] dark:border-white/10\">\n                Explore Free CBT Self-Help Guides\n              </a>\n            </div>\n          </div>\n        `;\n        screenerResult.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n      }\n    });\n  }\n\n  // ==========================================\n  // 7. Pricing Toggle (Monthly vs Annual 20% Off)\n  // ==========================================\n  const pricingToggle = document.getElementById('pricing-billing-toggle');\n  if (pricingToggle) {\n    pricingToggle.addEventListener('change', () => {\n      const isAnnual = pricingToggle.checked;\n      const priceAmounts = document.querySelectorAll('[data-monthly-price]');\n      const billingLabels = document.querySelectorAll('.billing-cycle-label');\n\n      priceAmounts.forEach(el => {\n        const monthly = parseFloat(el.getAttribute('data-monthly-price'));\n        const yearly = parseFloat(el.getAttribute('data-yearly-price')) || Math.round(monthly * 0.8);\n        el.textContent = isAnnual ? yearly : monthly;\n      });\n\n      billingLabels.forEach(lbl => {\n        lbl.textContent = isAnnual ? '/session (billed annually)' : '/session';\n      });\n\n      window.showToast(isAnnual ? 'Applied 20% Annual Care Plan Discount!' : 'Switched to Standard Pay-Per-Session Plan', 'info');\n    });\n  }\n\n  // ==========================================\n  // 8. Dynamic Filter & Search Engine\n  // ==========================================\n  function initFilterEngine(filterBtnAttr, cardAttr, searchInputId) {\n    const filterBtns = document.querySelectorAll(`[${filterBtnAttr}]`);\n    const cards = document.querySelectorAll(`[${cardAttr}]`);\n    const searchInput = document.getElementById(searchInputId);\n\n    if (!filterBtns.length && !cards.length && !searchInput) return;\n\n    let currentFilter = 'all';\n    let currentSearch = '';\n\n    function applyFilter() {\n      cards.forEach(card => {\n        const categories = (card.getAttribute(cardAttr) || '').toLowerCase();\n        const text = (card.textContent || '').toLowerCase();\n\n        const matchesFilter = currentFilter === 'all' || categories.includes(currentFilter.toLowerCase());\n        const matchesSearch = !currentSearch || text.includes(currentSearch.toLowerCase());\n\n        if (matchesFilter && matchesSearch) {\n          card.classList.remove('hidden');\n          card.style.opacity = '1';\n          card.style.transform = 'translateY(0)';\n        } else {\n          card.classList.add('hidden');\n          card.style.opacity = '0';\n          card.style.transform = 'translateY(10px)';\n        }\n      });\n    }\n\n    filterBtns.forEach(btn => {\n      btn.addEventListener('click', () => {\n        currentFilter = btn.getAttribute(filterBtnAttr) || 'all';\n\n        filterBtns.forEach(b => {\n          b.classList.remove('bg-[#D7B7A5]', 'text-white', 'shadow-md');\n          b.classList.add('bg-white', 'dark:bg-[#17232b]', 'text-[#27343B]', 'dark:text-[#EBF1F4]');\n        });\n        btn.classList.remove('bg-white', 'dark:bg-[#17232b]', 'text-[#27343B]', 'dark:text-[#EBF1F4]');\n        btn.classList.add('bg-[#D7B7A5]', 'text-white', 'shadow-md');\n\n        applyFilter();\n      });\n    });\n\n    if (searchInput) {\n      searchInput.addEventListener('input', (e) => {\n        currentSearch = e.target.value.trim();\n        applyFilter();\n      });\n    }\n  }\n\n  initFilterEngine('data-service-filter', 'data-service-category', 'services-search-input');\n  initFilterEngine('data-therapist-filter', 'data-therapist-specialty', 'therapists-search-input');\n  initFilterEngine('data-blog-filter', 'data-blog-category', 'blog-search-input');\n\n  // ==========================================\n  // 9. FAQ Accordions\n  // ==========================================\n  document.querySelectorAll('.accordion-header').forEach(header => {\n    header.addEventListener('click', () => {\n      const content = header.nextElementSibling;\n      const icon = header.querySelector('.accordion-icon, .fa-chevron-down');\n      const isExpanded = content && !content.classList.contains('hidden');\n\n      const parent = header.closest('.accordion-group');\n      if (parent) {\n        parent.querySelectorAll('.accordion-content').forEach(c => c.classList.add('hidden'));\n        parent.querySelectorAll('.accordion-icon, .fa-chevron-down').forEach(i => i.classList.remove('rotate-180'));\n      }\n\n      if (!isExpanded && content) {\n        content.classList.remove('hidden');\n        if (icon) icon.classList.add('rotate-180');\n      }\n    });\n  });\n\n  // ==========================================\n  // 10. Sticky Glass Header Elevation & Back to Top\n  // ==========================================\n  const mainHeader = document.getElementById('main-header');\n  const backToTopBtn = document.getElementById('back-to-top');\n\n  window.addEventListener('scroll', () => {\n    if (mainHeader) {\n      if (window.scrollY > 20) {\n        mainHeader.classList.add('shadow-md');\n      } else {\n        mainHeader.classList.remove('shadow-md');\n      }\n    }\n\n    if (backToTopBtn) {\n      if (window.scrollY > 400) {\n        backToTopBtn.classList.remove('opacity-0', 'pointer-events-none');\n        backToTopBtn.classList.add('opacity-100', 'pointer-events-auto');\n      } else {\n        backToTopBtn.classList.add('opacity-0', 'pointer-events-none');\n        backToTopBtn.classList.remove('opacity-100', 'pointer-events-auto');\n      }\n    }\n  });\n\n  if (backToTopBtn) {\n    backToTopBtn.addEventListener('click', () => {\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    });\n  }\n\n  // ==========================================\n  // 11. Animated Stats Counters\n  // ==========================================\n  function initCounters() {\n    const counters = document.querySelectorAll('[data-counter-target]');\n    if (!counters.length) return;\n\n    const counterObserver = new IntersectionObserver((entries) => {\n      entries.forEach(entry => {\n        if (entry.isIntersecting) {\n          const el = entry.target;\n          const target = parseInt(el.getAttribute('data-counter-target'), 10);\n          const prefix = el.getAttribute('data-counter-prefix') || '';\n          const suffix = el.getAttribute('data-counter-suffix') || '';\n          const duration = 1600;\n          const startTime = performance.now();\n\n          function updateCount(currentTime) {\n            const elapsed = currentTime - startTime;\n            const progress = Math.min(elapsed / duration, 1);\n            const easeOut = 1 - Math.pow(1 - progress, 3);\n            const currentVal = Math.floor(easeOut * target);\n\n            el.textContent = `${prefix}${currentVal.toLocaleString()}${suffix}`;\n\n            if (progress < 1) {\n              requestAnimationFrame(updateCount);\n            } else {\n              el.textContent = `${prefix}${target.toLocaleString()}${suffix}`;\n            }\n          }\n\n          requestAnimationFrame(updateCount);\n          counterObserver.unobserve(el);\n        }\n      });\n    }, { threshold: 0.2 });\n\n    counters.forEach(c => counterObserver.observe(c));\n  }\n\n  // ==========================================\n  // 12. Toast Notification Engine\n  // ==========================================\n  window.showToast = function (message, type = 'success', duration = 5000) {\n    let container = document.getElementById('toast-container');\n    if (!container) {\n      container = document.createElement('div');\n      container.id = 'toast-container';\n      container.className = 'fixed bottom-5 right-5 rtl:right-auto rtl:left-5 z-50 flex flex-col gap-2.5 max-w-sm pointer-events-none';\n      document.body.appendChild(container);\n    }\n\n    const toast = document.createElement('div');\n    const isSuccess = type === 'success';\n    const isError = type === 'error';\n    const bgClass = isSuccess \n      ? 'bg-emerald-50 text-emerald-900 border-emerald-300 dark:bg-emerald-950 dark:text-emerald-100 dark:border-emerald-800'\n      : isError\n      ? 'bg-rose-50 text-rose-900 border-rose-300 dark:bg-rose-950 dark:text-rose-100 dark:border-rose-800'\n      : 'bg-[#F8F6F1] text-[#294657] border-[#EBF1F4] dark:bg-[#17232b] dark:text-[#F8F6F1] dark:border-white/10';\n\n    const icon = isSuccess \n      ? '<i class=\"fas fa-check-circle text-emerald-500 text-base shrink-0\"></i>'\n      : isError\n      ? '<i class=\"fas fa-exclamation-circle text-rose-500 text-base shrink-0\"></i>'\n      : '<i class=\"fas fa-heart text-[#D7B7A5] text-base shrink-0\"></i>';\n\n    toast.className = `flex items-center gap-3 p-4 rounded-2xl shadow-2xl border text-xs font-bold pointer-events-auto transition-all transform duration-300 opacity-0 translate-y-3 ${bgClass}`;\n    toast.innerHTML = `\n      ${icon}\n      <span class=\"flex-1 leading-snug\">${message}</span>\n      <button class=\"text-stone-400 hover:text-stone-700 dark:hover:text-stone-200 p-1\" onclick=\"this.parentElement.remove()\" aria-label=\"Dismiss toast\">\n        <i class=\"fas fa-times\"></i>\n      </button>\n    `;\n\n    container.appendChild(toast);\n    requestAnimationFrame(() => {\n      toast.classList.remove('opacity-0', 'translate-y-3');\n      toast.classList.add('opacity-100', 'translate-y-0');\n    });\n\n    setTimeout(() => {\n      toast.classList.add('opacity-0', 'translate-y-3');\n      setTimeout(() => toast.remove(), 300);\n    }, duration);\n  };\n\n  // Run on DOM Ready\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', initCounters);\n  } else {\n    initCounters();\n  }\n})();\n";
